import * as store from './store.js';
import {renderEvents,renderEvent,renderFood,mountEvents,eventStyles} from './events.js';
import {renderAdmin,renderStaff,mountAdmin,adminStyles} from './admin.js';
import {renderCommunity,renderMember,renderJoin,renderProfile,mountCommunity,communityStyles} from './community.js';
import {qrSvg} from './qr.js';
import {renderRickshawHome} from './home-v2.js';
import {mountMotion} from './motion.js';
import {mountRickshawStage} from './rickshaw-stage.js';
import {renderCulturePage,mountCultureTrail} from './culture-v3.js';

const $=s=>document.querySelector(s);
export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang='en';try{lang=localStorage.getItem('bss-language')||'en';}catch{}
let toastTimer,returnFocus,galleryFilter='All';
const icons={
arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',arrowUp:'<path d="M6 18 18 6M6 6h12v12"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3a4 4 0 0 1 0 8"/><circle cx="9" cy="7" r="4"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',star:'<path d="m12 3 2.8 5.7 6.3.9-4.6 4.5 1.1 6.3L12 17.4l-5.6 3 1.1-6.3L3 9.6l6.2-.9Z"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a17 17 0 0 1 0 18 17 17 0 0 1 0-18Z"/>',leaf:'<path d="M20 3s1 9-4 14-12 3-12-2 3-11 16-12ZM4 20 15 9"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m21 15-6-6L3 21"/>',ticket:'<path d="M3 7h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4V7Zm12 0v12"/>',utensils:'<path d="M4 3v6a3 3 0 0 0 6 0V3M7 3v18M19 3c-4 3-4 9 0 9V3Zm0 9v9"/>',shield:'<path d="m12 3 8 4v6c0 4-8 8-8 8S4 17 4 13V7Z"/><path d="m8 12 3 3 5-6"/>',settings:'<path d="m10 3-1 3-3 1-3 3v4l3 1 1 3 3 3h4l1-3 3-1 3-3v-4l-3-1-1-3-3-3Z"/><circle cx="12" cy="12" r="3"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18"/>',book:'<path d="M3 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H3Zm18 0h-6a3 3 0 0 0-3 3v15a4 4 0 0 1 4-2h5Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',instagram:'<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><path d="M17 7h.01"/>','layout-dashboard':'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="11" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="18" width="7" height="3" rx="1"/>','chart-no-axes-combined':'<path d="M3 3v18h18M7 16l4-5 4 2 6-8"/>','shopping-bag':'<path d="M4 7h16l1 14H3ZM8 7V5a4 4 0 0 1 8 0v2"/>','file-text':'<path d="M14 2H4v20h16V8Zm0 0v6h6M8 12h8m-8 4h8"/>'};
export const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.star}</svg>`;
const tx=(en,bn)=>lang==='bn'?bn:en;
const money=n=>`¥${Number(n||0).toLocaleString('en-US')}`;
const formatDate=d=>new Date(`${String(d).slice(0,10)}T12:00:00+09:00`).toLocaleDateString(lang==='bn'?'bn-BD':'en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Tokyo'});
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=String(message);$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function closeModal(){const root=$('#modal-root');root.innerHTML='';document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus();}
function modal(title,html,onMount){returnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="modal-close" data-close-modal aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${html}</div></section></div>`;document.body.style.overflow='hidden';const root=$('#modal-root');root.querySelector('[data-close-modal]').onclick=closeModal;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});root.querySelector('.modal-close').focus();onMount?.(root);}
function navigate(path){if(location.hash===`#${path}`)render();else location.hash=path;}
function showTicket(ticket,type='event'){
 const s=store.getState(),food=type==='food'||type==='order',event=s.events.find(e=>e.id===ticket.eventId),token=ticket.qrToken||ticket.id;
 const html=`<div class="qr-ticket"><span class="badge badge-demo">DEMO ${food?'FOOD PICKUP':'EVENT ENTRY'} TICKET</span><h3>${esc(event?.title||'Community gathering')}</h3><p class="small muted">${esc(event?.date?formatDate(event.date):'')} · ${esc(food?ticket.pickup:event?.location||'')}</p>${qrSvg(token)}<div class="ticket-code">${esc(ticket.id)}</div><div class="ticket-summary">${food?(ticket.items||[]).map(i=>`<div class="order-line"><span>${i.qty} × ${esc(i.name)}</span><b>${money(i.price*i.qty)}</b></div>`).join(''):`<div class="order-line"><span>Reserved for</span><b>${esc(ticket.name)}</b></div>`}<div class="order-line"><span>Status</span><b>${esc((ticket.status||'confirmed').replaceAll('_',' '))}</b></div>${food?`<div class="order-line"><span>${ticket.paymentStatus==='paid'?'Cash recorded':'Payment due at pickup'}</span><b>${money(ticket.total)}</b></div>`:''}</div><p class="ticket-note">${food?'This is your food pickup code, separate from event admission. Show it at the food counter.':'Show this code at the event check-in desk. Food orders have their own pickup code.'} This demo ticket does not grant entry to a real event.</p><button class="btn btn-primary" id="ticket-print">${icon('download')} Save / print ticket</button><button class="btn btn-secondary" id="ticket-copy">Copy QR token</button></div>`;
 modal(food?'Your food ticket':'Your place is saved',html,root=>{root.querySelector('#ticket-print').onclick=()=>window.print();root.querySelector('#ticket-copy').onclick=async()=>{try{await navigator.clipboard.writeText(token);toast('Ticket token copied.');}catch{modal('Ticket token',`<p class="small">Copy this reference for manual staff lookup:</p><input class="search-input" value="${esc(token)}" readonly>`);}};});
}
const ctx={store,esc,icon,toast,modal,closeModal,navigate,render,formatDate,money,showTicket};
const extraStyles=document.createElement('style');extraStyles.textContent=[eventStyles,adminStyles,communityStyles, '.cart-summary{color:var(--green)} .hero h1{font-family:var(--serif)} .community-section .community-grid{grid-template-columns:1.1fr 2fr;gap:70px} @media(max-width:850px){.community-section .community-grid{grid-template-columns:1fr;gap:35px}}'].join('\n');document.head.append(extraStyles);
for(const id of ['rickshaw-theme','rickshaw-inner-theme','culture-theme','community-wall-theme','rickshaw-v4-theme']){const link=document.getElementById(id);if(link)document.head.append(link);}

function communitySettings(){const s=store.getState().settings||{};let instagram='https://www.instagram.com/tiu.bss/';try{const u=new URL(s.instagram||instagram);if(u.protocol==='https:')instagram=u.href;}catch{}return {title:s.title||'TIU Bangladesh Student Society',instagram,email:/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.email||'')?s.email:''};}

function brand(){return `<a class="brand" href="#/" aria-label="TIU BSS home"><span class="brand-symbol" aria-hidden="true"><img src="assets/rickshaw-flower.svg" alt="" width="49" height="49"></span><span class="brand-name">TIU BSS<small>${esc(communitySettings().title.replace(/^TIU\s+/i,''))}</small></span></a>`;}
function header(){const route=location.hash||'#/',p=store.getState().profile;return `<div class="top-ribbon"><span>${tx('ROOTED IN BANGLADESH','শিকড় বাংলাদেশে')}</span><span class="ribbon-dot"></span><span>${tx('GROWING TOGETHER IN JAPAN','একসাথে বেড়ে উঠি জাপানে')}</span></div><div class="header-surface"><div class="navbar">${brand()}<nav class="nav-links" id="nav-links" aria-label="Main navigation">${[['/events','Gatherings','আয়োজন'],['/community','Our people','আমাদের মানুষ'],['/gallery','The gallery','গ্যালারি'],['/culture','Our roots','আমাদের শিকড়']].map(([href,en,bn])=>`<a href="#${href}" class="${route.startsWith('#'+href)?'active':''}">${tx(en,bn)}</a>`).join('')}</nav><div class="nav-tools"><button class="lang-toggle" data-global="language" aria-label="Switch language"><span class="${lang==='en'?'selected':''}">EN</span><span>/</span><span class="${lang==='bn'?'selected':''}">বাংলা</span></button><a class="btn btn-primary nav-join" href="#/${p?'profile':'join'}">${p?tx('My profile','আমার প্রোফাইল'):tx('Find your people','যুক্ত হোন')} ${icon('arrowUp')}</a><button class="nav-menu" data-global="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button></div></div></div>`;}
function footer(){return `<div class="footer"><div class="footer-inner"><div class="footer-main"><div class="footer-about">${brand()}<p>A little piece of Bangladesh. A community in Japan.<br>For students, alumni, and everyone who calls us home.</p><a class="text-link" href="${esc(communitySettings().instagram)}" target="_blank" rel="noopener noreferrer">${icon('instagram')} Our Instagram ${icon('arrowUp')}</a></div><div class="footer-links"><div><h4>Come together</h4><a href="#/events">Events & gatherings</a><a href="#/community">Our community</a><a href="#/alumni">Alumni network</a><a href="#/mentorship">Find a mentor</a></div><div><h4>Get involved</h4><a href="#/volunteer">Volunteer with us</a><a href="#/committee">Our committee</a><a href="#/partners">Partner with us</a><a href="#/contact">Say hello</a></div><div><h4>Your space</h4><a href="#/profile">My profile & tickets</a><a href="#/news">Community journal</a><a href="#/culture">Bangladesh ↔ Japan</a><a href="#/admin">Admin workspace</a><a href="#/staff/food">Food counter</a></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${esc(communitySettings().title)} · Made with roots & heart.</span><span class="footer-demo" title="Sample data is saved on this browser only">Interactive demo</span><button class="rk-motion-toggle" data-motion-toggle type="button" aria-pressed="false"><span data-motion-label>Pause motion</span></button><span><a href="#/privacy">Privacy</a><a href="#/terms">Community guidelines</a><a href="#/setup">Setup status</a></span></div></div></div>`;}
function renderHome(){return renderRickshawHome(ctx,tx);}
function renderGallery(){const s=store.getState(),cats=['All',...new Set(s.gallery.map(g=>g.category))],rows=s.gallery.filter(g=>galleryFilter==='All'||g.category===galleryFilter);return `<section class="page-container"><div class="page-heading"><p class="eyebrow">COLOUR. CULTURE. COMMUNITY.</p><h1>A little gallery.<br>A lot of us.</h1><p>Explore the colours that inspired our home. Community photographs and new albums can be added from the admin workspace.</p></div><div class="toolbar">${cats.map(x=>`<button class="filter-chip ${galleryFilter===x?'active':''}" data-global="gallery-filter" data-filter="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="gallery-grid">${rows.map(g=>`<button class="gallery-tile" data-global="gallery" data-id="${esc(g.id)}"><img src="${esc(g.image)}" alt="${esc(g.caption||g.title)}" loading="lazy"><span class="gallery-label"><small>${esc(g.category)}</small><b>${esc(g.title)}</b></span></button>`).join('')||'<div class="empty-state">No images in this collection yet.</div>'}</div><p class="demo-note">Artwork references supplied for this project. Images shown here are not photographs of TIU BSS events.</p></section>`;}
function renderAbout(){return `<section class="page-container"><div class="about-banner"><div><p class="eyebrow">OUR STORY IS STILL BEING WRITTEN</p><h1>Home is a feeling.<br>We find it together.</h1><p>TIU Bangladesh Student Society is a space for Bangladeshi students, alumni, and friends at Tokyo International University to connect through shared roots and new experiences.</p><p>Whether you are finding your feet in Japan, building your next chapter, or simply looking for a familiar conversation — there is room for you here.</p><a class="btn btn-primary" href="#/join">Join our next chapter ${icon('arrowUp')}</a></div><img src="assets/rickshaw-cutout-v4.webp" alt="Original painted Bangladeshi rickshaw with peacocks and roses"></div><div class="feature-grid"><article class="feature-card">${icon('leaf')}<h3>Keep our roots close.</h3><p>A place for our language, food, art, and traditions to travel with us.</p><a class="text-link" href="#/gallery">Explore our culture ${icon('arrowUp')}</a></article><article class="feature-card">${icon('heart')}<h3>Show up for each other.</h3><p>From everyday questions to big moments, community begins with being there.</p><a class="text-link" href="#/volunteer">Give your time ${icon('arrowUp')}</a></article><article class="feature-card">${icon('globe')}<h3>Grow beyond borders.</h3><p>Connect student curiosity with alumni experience and make room for new possibilities.</p><a class="text-link" href="#/alumni">Meet our alumni ${icon('arrowUp')}</a></article></div></section>`;}
function renderNews(id){const news=store.getState().news.filter(n=>n.status==='published');const n=news.find(n=>n.id===id);if(id&&!n)return missing();if(n)return `<section class="page-container article"><a class="text-link" href="#/news">← Community journal</a><div class="page-heading" style="margin-top:30px"><p class="eyebrow">${esc(n.category)} · SAMPLE STORY</p><h1>${esc(n.title)}</h1><p>${formatDate(n.date)}</p></div>${n.image?`<img src="${esc(n.image)}" alt="${esc(n.title)}" style="border-radius:10px;max-height:380px;width:100%;object-fit:cover;margin-bottom:30px">`:''}${esc(n.body||n.excerpt).split('\n').map(p=>`<p>${p}</p>`).join('')}</section>`;return `<section class="page-container"><div class="page-heading"><p class="eyebrow">THE COMMUNITY JOURNAL</p><h1>Stories from our corner.</h1><p>Announcements, reflections, and the little things that bring us closer.</p></div><div class="event-grid">${news.map(n=>`<article class="event-card"><a class="event-art" href="#/news/${esc(n.id)}"><img src="${esc(n.image||'assets/folk-hero.webp')}" alt="${esc(n.title)}"><span class="badge">Sample story</span></a><div class="event-info"><p class="eyebrow">${esc(n.category)}</p><h3>${esc(n.title)}</h3><p class="small muted">${esc(n.excerpt||'')}</p><a class="text-link" href="#/news/${esc(n.id)}">Read the story ${icon('arrowUp')}</a></div></article>`).join('')||'<div class="empty-state">New stories will appear here.</div>'}</div></section>`;}
function renderParticipate(type){const content={volunteer:['LEND A LITTLE. MEAN A LOT.','Good things happen<br>when we show up.','From greeting guests to making food counters run smoothly, every helping hand makes our community stronger.','Volunteer interests',['Events & hospitality','Design & photography','Food counter','Community support']],mentorship:['A CONVERSATION CAN CHANGE A CHAPTER.','A little guidance.<br>A new possibility.','Connect with community members who are willing to share their experiences of studying, working, and finding their way in Japan.','Looking for guidance in',['Career direction','Life in Japan','University experience','Skills & portfolio']],partners:['MAKE SOMETHING MEANINGFUL TOGETHER.','Shared roots.<br>Shared possibilities.','Support cultural gatherings, student opportunities, and connections that make our community stronger.','Partnership interest',['Event support','Food & hospitality','Career opportunities','Community collaboration']],contact:['SAY HELLO. WE’RE LISTENING.','Let’s start<br>a conversation.','Have an idea, a question, or something you would love to bring to this community? We would love to hear it.','What is it about?',['General inquiry','Events','Membership','A new idea']]};const [eye,title,desc,label,opts]=content[type]||content.contact;const p=store.getState().profile;return `<section class="page-container"><div class="connect-grid"><div class="page-heading"><p class="eyebrow">${eye}</p><h1>${title}</h1><p>${desc}</p><p><a class="text-link" href="${esc(communitySettings().instagram)}" target="_blank" rel="noopener noreferrer">Find us on Instagram ${icon('arrowUp')}</a></p>${type==='contact'&&communitySettings().email?`<p><a class="text-link" href="mailto:${esc(communitySettings().email)}">${esc(communitySettings().email)} ${icon('mail')}</a></p>`:''}${type==='mentorship'?'<a class="btn btn-secondary" href="#/alumni">Explore alumni profiles ↗</a>':''}${type==='partners'?renderPartnersList():''}</div><div class="panel"><h2>${type==='volunteer'?'Count me in.':type==='mentorship'?'Find your next conversation.':'We’d love to hear from you.'}</h2><p>This demo saves requests in this browser’s admin inbox. It does not send a message to TIU BSS.</p><form id="participation-form" data-kind="${type}"><div class="field"><label for="request-name">Your name</label><input id="request-name" name="name" value="${esc(p?.name||'')}" required maxlength="100"></div><div class="field"><label for="request-email">Email</label><input id="request-email" type="email" name="email" value="${esc(p?.email||'')}" required></div><div class="field"><label for="request-topic">${label}</label><select id="request-topic" name="topic">${opts.map(o=>`<option>${esc(o)}</option>`).join('')}</select></div><div class="field"><label for="request-message">Tell us a little more</label><textarea id="request-message" name="message" rows="4" required maxlength="2000"></textarea></div><label class="checkbox"><input type="checkbox" required> I understand this is a local demonstration.</label><button class="btn btn-primary" type="submit">Save demo ${type==='volunteer'?'application':'request'} ${icon('arrowUp')}</button></form></div></div></section>`;}

function renderPartnersList(){return (store.getState().partners||[]).map(p=>`<article class="panel">${p.logo?`<img src="${esc(p.logo)}" alt="${esc(p.name)} logo" style="max-height:65px;max-width:160px;margin-bottom:15px;object-fit:contain">`:''}<h3>${esc(p.name)}</h3><p>${esc(p.description||'')}</p>${/^https:\/\//i.test(p.website||'')?`<a class="text-link" href="${esc(p.website)}" target="_blank" rel="noopener noreferrer">Visit partner ↗</a>`:''}<small class="muted">Demo workspace entry</small></article>`).join('');}

function renderCommittee(){const roster=store.getState().committee||[];if(roster.length)return `<section class="page-container"><div class="page-heading"><p class="eyebrow">THE PEOPLE BEHIND THE GATHERINGS</p><h1>Many hands.<br>One community.</h1><p>Meet the people shaping the next chapter of TIU BSS. Roster entries in this preview are saved locally by the demo admin.</p></div><div class="member-grid">${roster.map(m=>`<article class="member-card">${m.photo?`<img class="avatar" src="${esc(m.photo)}" alt="${esc(m.name)}">`:`<div class="avatar">${esc(m.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div>`}<h3>${esc(m.name)}</h3><span class="badge">${esc(m.role)}</span><p>${esc(m.term||'')}</p><p>${esc(m.bio||'')}</p>${m.memberId?`<a class="text-link" href="#/members/${esc(m.memberId)}">Community profile ↗</a>`:''}</article>`).join('')}</div></section>`;return `<section class="page-container"><div class="page-heading"><p class="eyebrow">THE PEOPLE BEHIND THE GATHERINGS</p><h1>Many hands.<br>One community.</h1><p>Meet the committee shaping the next chapter of TIU BSS.</p></div><div class="empty-state">${icon('users')}<h3>Our official roster is on its way.</h3><p>Committee names, terms, and photographs have not been supplied.<br>Follow TIU BSS for verified community updates.</p><a class="btn btn-primary" href="${esc(communitySettings().instagram)}" target="_blank" rel="noopener noreferrer">Community Instagram ↗</a></div><section class="join-band" style="margin:35px 0 0"><div><h2>Be part of what comes next.</h2><p>Your ideas and your time can help shape this community.</p></div><a class="btn btn-yellow" href="#/volunteer">Get involved ↗</a></section></section>`;}
function renderLegal(terms=false){return `<section class="page-container article"><div class="page-heading"><p class="eyebrow">${terms?'A COMMUNITY BUILT ON CARE':'YOUR SPACE, YOUR CHOICE'}</p><h1>${terms?'Community guidelines':'Your privacy matters.'}</h1><p>Preview information · Updated 12 October 2026</p></div>${terms?`<h2>Make room for each other.</h2><p>Treat community members with respect. Celebrate differences, welcome newcomers, and do not share another person’s details without their permission.</p><h2>Share responsibly.</h2><p>Submit photographs and content you have the right to share. Avoid harassment, impersonation, private information, and misleading event announcements.</p><h2>This is an interactive demonstration.</h2><p>Sample events are not official announcements. Demo tickets and food orders are for testing only and do not represent a real booking, purchase, or payment. Event organizers must supply official dates, menus, policies, and contact details before launch.</p>`:`<h2>What this preview stores.</h2><p>This website stores demo profile information, tickets, food orders, community posts and replies, forms, and admin edits in your browser’s local storage. This information is not sent to a Firebase project by the current demo. Use sample information; do not enter sensitive personal details.</p><h2>Directory visibility is your choice.</h2><p>Only demo profiles marked approved and opted into the directory appear in community listings. Email and phone are not shown on public profile cards. This local demo is not an authenticated multi-user privacy boundary.</p><h2>Export or remove your profile.</h2><p>Open My profile → Privacy to export your demo information or remove your profile. Reset demo in Admin → Settings clears all browser-local demo records. Clearing this browser’s site data also removes saved changes.</p><h2>Images and external services.</h2><p>Gallery uploads are stored on this device in demo mode. The interface requests fonts from Google Fonts and links to Instagram. It does not embed an Instagram feed. Live Firebase authentication, cloud uploads, and email are not connected.</p><h2>Before the community launch.</h2><p>The organization needs to approve its production privacy policy, contact details, retention periods, and operational processes. Live Firebase access rules and integrations must be configured and tested in the organization’s own project.</p>`}<a class="btn btn-secondary" href="#/profile">My profile & privacy ${icon('arrowUp')}</a></section>`;}
function renderSetup(){return `<section class="page-container article"><div class="page-heading"><p class="eyebrow">WEBSITE SETUP STATUS</p><h1>Your new home.<br>Ready to explore.</h1><p>This is a functional design demonstration. It is private to the site owner and uses sample data saved on this device.</p></div><div class="panel"><h2>Working in this demo</h2><p>Profile editing and directory consent; event creation and free registration; unique event QR tickets and manual check-in; food menus, inventory, cash-due checkout, kitchen stages, cash recording and one-time pickup; gallery uploads; news and announcements; a community wall with posts, replies, reactions and admin moderation; interactive cultural stories; requests and CSV reports.</p></div><div class="panel"><h2>Prepared in the source</h2><p>Firebase Auth adapter, private/public profile separation, role-secured Cloud Functions, capacity and stock transactions, one-time token redemption, Firestore and Storage rules, indexes, and deployment instructions.</p></div><div class="panel"><h2>Not connected</h2><p>Firebase project credentials and production screen integration, live multi-user accounts and cloud data, online payments, event email or push delivery, and camera scanning. Full production features such as refunds, waitlists, vouchers, and certificates still require implementation and testing.</p><p>Setting Firebase credentials alone does not switch the demo to live mode. The included adapter must be connected to the application screens and verified against the organization’s Firebase project.</p></div><div class="form-actions"><a href="#/admin" class="btn btn-primary">Explore admin ${icon('arrowUp')}</a><a href="#/join" class="btn btn-secondary">Try a member profile ${icon('arrowUp')}</a></div></section>`;}
function renderVerify(id){return `<section class="page-container"><div class="page-heading"><p class="eyebrow">CERTIFICATE VERIFICATION</p><h1>Check a certificate.</h1><p>Certificate issuance is not connected in this preview. No certificates will be shown as verified.</p></div><div class="panel"><form id="verify-form"><label class="field"><span>Certificate reference</span><input name="id" value="${esc(id||'')}" required maxlength="100"></label><button class="btn btn-primary">Check reference</button></form>${id?`<p class="form-error" style="margin-top:20px">No verifiable certificate is available for ${esc(id)}.</p>`:''}</div></section>`;}
function missing(){return `<section class="page-container empty-state"><h1>Let’s find your way back.</h1><p>This page is not here. There’s still plenty to explore.</p><a class="btn btn-primary" href="#/">Back to our home ${icon('arrow')}</a></section>`;}
function render(){const raw=(location.hash.slice(1)||'/').split('?')[0],parts=raw.split('/').filter(Boolean);let html;try{switch(parts[0]||'home'){case'home':html=renderHome();break;case'events':html=parts[2]==='food'?renderFood(ctx,parts[1]):parts[1]?renderEvent(ctx,parts[1]):renderEvents(ctx);break;case'community':html=renderCommunity(ctx);break;case'alumni':html=renderCommunity(ctx,true);break;case'members':html=renderMember(ctx,parts[1]);break;case'join':html=renderJoin(ctx);break;case'profile':html=renderProfile(ctx);break;case'admin':html=renderAdmin(ctx);break;case'staff':html=renderStaff(ctx,parts[1]);break;case'gallery':html=renderGallery();break;case'culture':html=renderCulturePage(ctx,tx);break;case'about':case'mission':case'history':html=renderAbout();break;case'news':html=renderNews(parts[1]);break;case'volunteer':case'mentorship':case'partners':case'contact':html=renderParticipate(parts[0]);break;case'committee':html=renderCommittee();break;case'privacy':html=renderLegal();break;case'terms':html=renderLegal(true);break;case'setup':html=renderSetup();break;case'verify-certificate':html=renderVerify(parts[1]);break;default:html=missing();}}catch(error){console.error(error);html=`<section class="page-container empty-state"><h1>Something needs a refresh.</h1><p>We couldn’t load this view. Your saved demo changes are still on this device.</p><button class="btn btn-primary" data-global="reload">Try again</button></section>`;}
 $('#site-header').innerHTML=header();$('#app').innerHTML=html.replace(/<main\b/g,'<section').replace(/<\/main>/g,'</section>');$('#site-footer').innerHTML=footer();document.documentElement.lang=lang;document.title=`${parts[0]&&parts[0]!=='home'?parts[0].charAt(0).toUpperCase()+parts[0].slice(1)+' · ':''}${communitySettings().title} — A world of belonging`;
 mountEvents(ctx);mountAdmin(ctx);mountCommunity(ctx);mountRoot();mountCultureTrail(ctx);mountRickshawStage(ctx);
 document.querySelectorAll('#app > .page-container > .page-heading, .events-page .event-card, .community-page .community-member-card, .food-page .food-card, .about-banner, .feature-card').forEach(el=>el.setAttribute('data-reveal',''));
 mountMotion();
}
function mountRoot(){const form=$('#participation-form');if(form)form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));const kind=form.dataset.kind;try{store.saveRecord(kind==='volunteer'?'volunteers':'messages',{...data,id:store.uid(kind),kind,status:'pending',createdAt:new Date().toISOString(),isDemo:true,userId:store.getState().profile?.id||null});form.reset();toast('Demo request saved. You can review it in the admin workspace.');}catch(err){toast(err.message);}};const verify=$('#verify-form');if(verify)verify.onsubmit=e=>{e.preventDefault();navigate('/verify-certificate/'+encodeURIComponent(new FormData(verify).get('id')));};}
document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});return;}const b=e.target.closest('[data-global]');if(!b)return;const action=b.dataset.global;if(action==='language'){lang=lang==='en'?'bn':'en';try{localStorage.setItem('bss-language',lang);}catch{}render();if(lang==='bn'&&!['#/','#'].includes(location.hash)&&location.hash)toast('বাংলা হোমপেজ ও নেভিগেশন চালু হয়েছে। কিছু সেকশন ইংরেজিতে রয়েছে।');}if(action==='menu'){$('#nav-links').classList.toggle('is-open');b.setAttribute('aria-expanded',$('#nav-links').classList.contains('is-open'));}if(action==='reload')render();if(action==='gallery-filter'){galleryFilter=b.dataset.filter;render();}if(action==='gallery'){const g=store.getState().gallery.find(g=>g.id===b.dataset.id);if(g)modal(g.title,`<img src="${esc(g.image)}" alt="${esc(g.caption||g.title)}"><p class="small muted" style="margin:17px 0 0">${esc(g.caption||'')}</p>`);}});
document.addEventListener('keydown',e=>{if(!$('#modal-root').children.length)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const nodes=[...$('#modal-root').querySelectorAll('button:not([disabled]),a,input,select,textarea,[tabindex="0"]')].filter(el=>!el.hidden);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key==='tiu-bss-demo-v1')render();});
window.addEventListener('offline',()=>toast('You’re offline. Demo actions still work after this page has loaded.'));
render();
